    input = sys.stdin.read
    data = input().split()

    n = int(data[0])
    strings = data[1:]

    # Create a dictionary to store the count of each suffix
    suffix_count = {}

    for s in strings:
        for i in range(len(s)):
            suffix = s[i:]
            if suffix in suffix_count:
                suffix_count[suffix] += 1
            else:
